grant select,insert,update,delete on public.hub_announcement_recipients,public.hub_announcement_polls,public.hub_announcement_poll_options,public.hub_announcement_poll_votes,public.hub_announcement_replies to authenticated;
create policy "pulse recipients select" on public.hub_announcement_recipients for select to authenticated using (user_id=auth.uid() or exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse recipients insert" on public.hub_announcement_recipients for insert to authenticated with check (exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse recipients update" on public.hub_announcement_recipients for update to authenticated using (user_id=auth.uid() or exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug)))) with check (user_id=auth.uid() or exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse recipients delete" on public.hub_announcement_recipients for delete to authenticated using (exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse polls select" on public.hub_announcement_polls for select to authenticated using (exists(select 1 from public.hub_announcement_recipients r where r.announcement_id=announcement_id and r.user_id=auth.uid()) or exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse polls insert" on public.hub_announcement_polls for insert to authenticated with check (exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse polls update" on public.hub_announcement_polls for update to authenticated using (exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug)))) with check (exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse polls delete" on public.hub_announcement_polls for delete to authenticated using (exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse poll options select" on public.hub_announcement_poll_options for select to authenticated using (exists(select 1 from public.hub_announcement_polls p where p.id=poll_id and (exists(select 1 from public.hub_announcement_recipients r where r.announcement_id=p.announcement_id and r.user_id=auth.uid()) or exists(select 1 from public.hub_announcements a where a.id=p.announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))))));
create policy "pulse poll options insert" on public.hub_announcement_poll_options for insert to authenticated with check (exists(select 1 from public.hub_announcement_polls p join public.hub_announcements a on a.id=p.announcement_id where p.id=poll_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse poll options update" on public.hub_announcement_poll_options for update to authenticated using (exists(select 1 from public.hub_announcement_polls p join public.hub_announcements a on a.id=p.announcement_id where p.id=poll_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug)))) with check (exists(select 1 from public.hub_announcement_polls p join public.hub_announcements a on a.id=p.announcement_id where p.id=poll_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse poll options delete" on public.hub_announcement_poll_options for delete to authenticated using (exists(select 1 from public.hub_announcement_polls p join public.hub_announcements a on a.id=p.announcement_id where p.id=poll_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse votes select" on public.hub_announcement_poll_votes for select to authenticated using (user_id=auth.uid() or exists(select 1 from public.hub_announcement_polls p join public.hub_announcements a on a.id=p.announcement_id where p.id=poll_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse votes insert" on public.hub_announcement_poll_votes for insert to authenticated with check (user_id=auth.uid() and exists(select 1 from public.hub_announcement_polls p join public.hub_announcement_recipients r on r.announcement_id=p.announcement_id where p.id=poll_id and r.user_id=auth.uid()) and exists(select 1 from public.hub_announcement_poll_options o where o.id=option_id and o.poll_id=poll_id));
create policy "pulse votes delete" on public.hub_announcement_poll_votes for delete to authenticated using (user_id=auth.uid());
create policy "pulse replies select" on public.hub_announcement_replies for select to authenticated using (recipient_user_id=auth.uid() or sender_user_id=auth.uid() or exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug))));
create policy "pulse replies insert" on public.hub_announcement_replies for insert to authenticated with check (sender_user_id=auth.uid() and exists(select 1 from public.hub_announcement_recipients r where r.announcement_id=announcement_id and r.user_id=recipient_user_id) and (recipient_user_id=auth.uid() or exists(select 1 from public.hub_announcements a where a.id=announcement_id and (a.created_by=auth.uid() or public.vlacora_can_manage_station(a.station_slug)))));
